  function cubeFace(points,value,fill){let art=`<polygon points="${points.map(p=>p.join(',')).join(' ')}" fill="${fill}" stroke="#41627a" stroke-width="1.7"/>`;for(const[u,v]of pips[value]){const x=points[0][0]+u*(points[1][0]-points[0][0])+v*(points[3][0]-points[0][0]),y=points[0][1]+u*(points[1][1]-points[0][1])+v*(points[3][1]-points[0][1]);art+=`<circle cx="${x}" cy="${y}" r="3.5" fill="#24445c"/>`;}return art;}
  function rollResult(p){let s={T:p.top,B:7-p.top,F:p.front,K:7-p.front,R:p.right,L:7-p.right};for(const m of p.moves){const a={...s};if(m==='R')Object.assign(s,{T:a.L,R:a.T,B:a.R,L:a.B});if(m==='L')Object.assign(s,{T:a.R,L:a.T,B:a.L,R:a.B});if(m==='U')Object.assign(s,{T:a.F,K:a.T,B:a.K,F:a.B});if(m==='D')Object.assign(s,{T:a.K,F:a.T,B:a.F,K:a.B});}return s[p.query==='bottom'?'B':'T'];}
