  function groupExplanation(p){if(p.kind==='group'&&p.mode==='group')return `묶음의 구슬 수는 1, 2, 3처럼 한 개씩 늘어나므로 ${p.position}번째 묶음에는 ${p.position}개가 있습니다. 파랑·노랑이 번갈아 나오므로 ${p.position%2?'홀수':'짝수'} 번째인 이 묶음은 ${p.position%2?'파란색':'노란색'}입니다.`;const counts=[];let total=0,k=0;while(total<p.position){k++;counts.push(p.kind==='runs'?k+1:k);total+=counts.at(-1);}const before=total-counts.at(-1);return `${k-1}번째 묶음까지는 ${counts.slice(0,-1).join('+')}=${before}개입니다. ${k}번째 묶음은 ${before+1}번째부터 ${total}번째까지입니다. ${p.kind==='runs'?`첫 구슬 ${before+1}번째는 하얀색이고 나머지는 파란색이므로 ${p.position}번째는 ${p.position===before+1?'하얀색':'파란색'}입니다.`:`이 묶음은 ${k%2?'파란색':'노란색'}이므로 ${p.position}번째도 같은 색입니다.`}`;}
